const CACHE = `kq-${BUILD_ID}`;
const SCOPE = new URL(self.registration.scope);

self.addEventListener('install', (event) => {
  // Precache the whole build. A new build waits until the page says the player is ready to swap.
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((p) => new URL(p, SCOPE).toString()))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k.startsWith('kq-') && k !== CACHE).map((k) => caches.delete(k))),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
  if (event.data === 'build-id') event.source?.postMessage({ buildId: BUILD_ID });
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Only our own static files. The API and anything else go straight to the network.
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;

  if (req.mode === 'navigate') {
    // App shell: the cached index for this build, so an update never swaps mid-game.
    event.respondWith(
      caches.open(CACHE).then(async (cache) => (await cache.match(SCOPE.toString())) ?? fetch(req)),
    );
    return;
  }
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: false });
      if (hit) return hit;
      const res = await fetch(req);
      // Late assets (fonts for other scripts, for example) are kept for offline use.
      if (res.ok && url.pathname.startsWith(`${SCOPE.pathname}assets/`)) cache.put(req, res.clone());
      return res;
    }),
  );
});
